// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Placement) predicate.Placement {
	return predicate.Placement(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Placement) predicate.Placement {
	return predicate.Placement(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Placement) predicate.Placement {
	return predicate.Placement(sql.NotPredicates(p))
}
